using DevExpress.XtraEditors;
using DevExpress.XtraGrid;
using DevExpress.XtraGrid.Views.Grid;
using POS.Core.Abstractions;
using POS.Core.Security;
using POS.Data.Context;
using POS.Models.Operations;
using POS.Services;
using POS.Services.Inventory;
using POS.Services.Security;
using System;
using System.ComponentModel;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;

namespace POS.Forms
{
    public sealed class ucStockCounts : XtraUserControl
    {
        private readonly StockCountService _service; private readonly InventoryService _products; private readonly InventoryLedgerService _ledger; private readonly GridControl _grid = new GridControl(); private readonly GridView _view = new GridView(); private readonly SimpleButton _new = new SimpleButton { Text = "New stock count" }; private readonly LabelControl _status = new LabelControl(); private int _page = 1;
        public ucStockCounts(StockCountService service, InventoryService products, InventoryLedgerService ledger) { _service = service ?? throw new ArgumentNullException(nameof(service)); _products = products ?? throw new ArgumentNullException(nameof(products)); _ledger = ledger ?? throw new ArgumentNullException(nameof(ledger)); Dock = DockStyle.Fill; BuildUi(); Load += (s, e) => LoadPage(); }
        private void BuildUi() { var head = new PanelControl { Dock = DockStyle.Top, Height = 46 }; _new.SetBounds(12, 9, 130, 27); _status.SetBounds(155, 14, 500, 20); head.Controls.AddRange(new Control[] { _new, _status }); _grid.Dock = DockStyle.Fill; _grid.MainView = _view; _grid.ViewCollection.Add(_view); _view.OptionsBehavior.Editable = false; _view.OptionsView.ShowGroupPanel = false; _view.Columns.AddVisible(nameof(StockCountSummaryDTO.Id), "Count"); _view.Columns.AddVisible(nameof(StockCountSummaryDTO.Status), "Status"); _view.Columns.AddVisible(nameof(StockCountSummaryDTO.CreatedByUserId), "Created by"); _view.Columns.AddVisible(nameof(StockCountSummaryDTO.CreatedUtc), "Created (UTC)"); _view.Columns.AddVisible(nameof(StockCountSummaryDTO.PostedUtc), "Posted (UTC)"); _view.Columns.AddVisible(nameof(StockCountSummaryDTO.ProductCount), "Products"); Controls.Add(_grid); Controls.Add(head); _new.Click += (s, e) => Open(null); _view.DoubleClick += (s, e) => Open(_view.GetFocusedRow() as StockCountSummaryDTO); }
        private void LoadPage() { try { var result = _service.SearchHistory(new StockCountSearchDTO { PageNumber = _page, PageSize = 50 }); _grid.DataSource = new BindingList<StockCountSummaryDTO>(result.Items.ToList()); _status.Text = string.Format("Page {0} of {1} - {2:N0} count(s)", result.PageNumber, result.TotalPages, result.TotalCount); } catch (Exception ex) { XtraMessageBox.Show(this, ex.Message, "Stock counts", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
        private void Open(StockCountSummaryDTO count) { using (var form = new frmStockCount(_service, _products, _ledger, count)) if (form.ShowDialog(FindForm()) == DialogResult.OK) LoadPage(); }
    }

    public sealed class frmStockCount : XtraForm
    {
        private readonly StockCountService _service; private readonly InventoryService _products; private readonly InventoryLedgerService _ledger; private readonly StockCountSummaryDTO _existing; private readonly LookUpEdit _product = new LookUpEdit(); private readonly SpinEdit _counted = new SpinEdit(); private readonly MemoEdit _reason = new MemoEdit(); private readonly GridControl _grid = new GridControl(); private readonly GridView _view = new GridView(); private readonly SimpleButton _save = new SimpleButton { Text = "Save draft" }, _post = new SimpleButton { Text = "Post count" }; private readonly System.Collections.Generic.List<StockCountQuantityDTO> _items = new System.Collections.Generic.List<StockCountQuantityDTO>();
        public frmStockCount(StockCountService service, InventoryService products, InventoryLedgerService ledger, StockCountSummaryDTO existing) { _service = service; _products = products; _ledger = ledger; _existing = existing; Text = existing == null ? "New stock count" : "Stock count #" + existing.Id; Size = new Size(820, 520); StartPosition = FormStartPosition.CenterParent; BuildUi(); LoadData(); }
        private void BuildUi() { var top = new PanelControl { Dock = DockStyle.Top, Height = 92 }; _product.SetBounds(12, 12, 260, 26); _counted.SetBounds(280, 12, 100, 26); var add = new SimpleButton { Text = "Add line" }; add.SetBounds(390, 12, 80, 26); _reason.SetBounds(12, 48, 470, 30); _reason.Properties.NullText = "Required reason"; top.Controls.AddRange(new Control[] { _product, _counted, add, _reason }); _grid.Dock = DockStyle.Fill; _grid.MainView = _view; _grid.ViewCollection.Add(_view); _view.OptionsBehavior.Editable = false; _view.OptionsView.ShowGroupPanel = false; _view.Columns.AddVisible(nameof(StockCountDetailLineDTO.CurrentProductName), "Product"); _view.Columns.AddVisible(nameof(StockCountDetailLineDTO.CurrentSku), "SKU"); _view.Columns.AddVisible(nameof(StockCountDetailLineDTO.ExpectedQuantity), "Expected"); _view.Columns.AddVisible(nameof(StockCountDetailLineDTO.CountedQuantity), "Counted"); _view.Columns.AddVisible(nameof(StockCountDetailLineDTO.Variance), "Variance"); var bottom = new PanelControl { Dock = DockStyle.Bottom, Height = 45 }; _save.SetBounds(12, 8, 100, 27); _post.SetBounds(120, 8, 100, 27); bottom.Controls.AddRange(new Control[] { _save, _post }); Controls.Add(_grid); Controls.Add(bottom); Controls.Add(top); add.Click += (s, e) => AddLine(); _save.Click += (s, e) => Submit(false); _post.Click += (s, e) => Submit(true); _product.Properties.DisplayMember = "Name"; _product.Properties.ValueMember = "Id"; _product.Properties.NullText = "Select product"; }
        private void LoadData() { try { _product.Properties.DataSource = _products.SearchProducts(new ProductSearchDTO { IsActive = true, PageSize = 200 }).Items; if (_existing != null) { var detail = _service.GetDetails(_existing.Id); _items.AddRange(detail.Items.Select(x => new StockCountQuantityDTO { ProductId = x.ProductId, ExpectedQuantity = x.ExpectedQuantity, CountedQuantity = x.CountedQuantity })); } RefreshGrid(); } catch (Exception ex) { XtraMessageBox.Show(this, ex.Message, "Stock count", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
        private void AddLine() { try { if (_product.EditValue == null) throw new System.ComponentModel.DataAnnotations.ValidationException("Select a product."); var id = Convert.ToInt32(_product.EditValue); if (_items.Any(x => x.ProductId == id)) throw new System.ComponentModel.DataAnnotations.ValidationException("This product is already in the count."); _items.Add(new StockCountQuantityDTO { ProductId = id, ExpectedQuantity = _ledger.GetQuantityOnHand(id), CountedQuantity = Convert.ToInt32(_counted.Value) }); RefreshGrid(); } catch (Exception ex) { XtraMessageBox.Show(this, ex.Message, "Stock count", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
        private void RefreshGrid() { _grid.DataSource = new BindingList<StockCountDetailLineDTO>(_items.Select(x => new StockCountDetailLineDTO { ProductId = x.ProductId, ExpectedQuantity = x.ExpectedQuantity, CountedQuantity = x.CountedQuantity, CurrentProductName = _product.Properties.GetDataSourceRowByKeyValue(x.ProductId) is ProductSummaryDTO p ? p.Name : x.ProductId.ToString(), CurrentSku = _product.Properties.GetDataSourceRowByKeyValue(x.ProductId) is ProductSummaryDTO q ? q.Sku : null }).ToList()); }
        private void Submit(bool post) { try { if (_items.Count == 0 || string.IsNullOrWhiteSpace(_reason.Text)) throw new System.ComponentModel.DataAnnotations.ValidationException("Add at least one line and provide a reason."); _save.Enabled = _post.Enabled = false; if (_existing == null) { var request = new StockCountPostingDTO { RequestId = Guid.NewGuid(), Reason = _reason.Text, Items = _items }; if (post) _service.PostCount(request); else _service.CreateDraft(request); } else if (post) _service.PostDraft(_existing.Id, _reason.Text, _existing.RowVersion); else _service.UpdateDraft(new StockCountDraftUpdateDTO { CountId = _existing.Id, ExpectedRowVersion = _existing.RowVersion, Items = _items }); DialogResult = DialogResult.OK; Close(); } catch (Exception ex) { _save.Enabled = _post.Enabled = true; XtraMessageBox.Show(this, ex.Message, "Unable to save stock count", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
    }
}
